/**
 * agents.md: the routing guide for AI agents (external agents over MCP or the vault, and Kortex's
 * own AI functions). One source for every copy:
 *   - repo root `agents.md` (generated by `scripts/agents-index.mjs`, plus the repo map),
 *   - the MCP resource `kortex://agents.md` and `brain_get_item { id: "agents.md" }` (plus the
 *     user's live folder index),
 *   - `<vault>/agents.md`, written by md-sync (plus the local folder index).
 * Everything structural comes from code constants, so the guide cannot drift from the schema.
 */
import {
  DOMAIN_OBJECT_FOLDERS,
  DOMAIN_OBJECT_TYPES,
  ITEM_STATUSES,
  KNOWLEDGE_ITEM_TYPES,
  PRIORITIES,
  SYSTEM_FOLDER_PATHS,
  type DomainObjectType,
} from "@kortex/db";
import { OBJECT_FIELDS } from "./objects";
import { brand } from "@kortex/i18n";

/** Id that `brain_get_item` accepts instead of a uuid to return this guide. */
export const AGENTS_GUIDE_ID = "agents.md";
/** URI of the MCP resource with this guide. */
export const AGENTS_GUIDE_URI = "kortex://agents.md";
/** File name of the guide in the repo root and in the vault root. */
export const AGENTS_FILE_NAME = "agents.md";

