export interface FolderCount {
  folder_path: string;
  /** Items directly in this folder (not counting sub-folders). */
  items: number;
}

const json = (v: unknown) => JSON.stringify(v);

/** Public address of this deployment's remote MCP server (`MCP_PUBLIC_URL`), if the process knows one. */
function publicMcpUrl(): string | undefined {
  const raw = typeof process === "undefined" ? undefined : process.env.MCP_PUBLIC_URL;
  return raw?.trim().replace(/\/+$/, "") || undefined;
}

/**
 * The static part of the guide (no user data). `heading` false omits the H1 (for embedding).
 * `mcpUrl` names the remote MCP server; by default the one this process serves, else none.
 */
export function renderAgentsGuide(opts: { heading?: boolean; mcpUrl?: string | null } = {}): string {
  const mcpUrl = opts.mcpUrl === undefined ? publicMcpUrl() : (opts.mcpUrl ?? undefined);
  const out: string[] = [];
  if (opts.heading !== false) out.push("# Kortex agents guide", "");
  out.push(
    "Kortex is the user's AI-native second brain: Markdown knowledge items in folders, with tags, domain objects and tasks, stored in Supabase and mirrored as a Markdown vault. This guide tells agents where things live and how to route reads and writes.",
    "",
    "Access paths:",
    "",
    `- **MCP server** (\`kortex-brain\`): ${mcpUrl ? `remote \`${mcpUrl}/mcp\` (OAuth)` : "remote over HTTP with OAuth (the address of your Kortex MCP server)"} or local stdio/HTTP. Preferred for agents.`,
    `- **This guide over MCP**: resource \`${AGENTS_GUIDE_URI}\` or \`brain_get_item { "id": "${AGENTS_GUIDE_ID}" }\`, both with the user's live folder index.`,
    "- **Vault** (`~/KortexVault`, synced both ways by md-sync): plain `.md` files with YAML frontmatter; its root `agents.md` is this guide with the local folder index.",
    "",
    "## Vault structure",
    "",
    "| Folder | Holds | Item types |",
    "| --- | --- | --- |",
    ...SYSTEM_FOLDER_PATHS.map((f) => {
      const g = SYSTEM_FOLDER_GUIDE[f] ?? { holds: "", types: "" };
      return `| \`${f}\` | ${g.holds} | ${g.types} |`;
    }),
    "",
    "## Routing rules (what goes where)",
    "",
    ...ROUTING_RULES.map((r, i) => `${i + 1}. ${r}`),
    "",
    "## Item types",
    "",
    KNOWLEDGE_ITEM_TYPES.map((t) => `\`${t}\``).join(", "),
    "",
    "## Domain objects",
    "",
    "| Type | Folder | `metadata` fields |",
    "| --- | --- | --- |",
    ...DOMAIN_OBJECT_TYPES.map(
      (t: DomainObjectType) =>
        `| \`${t}\` | \`${DOMAIN_OBJECT_FOLDERS[t]}\` | ${OBJECT_FIELDS[t].map((f) => `\`${f}\``).join(", ")} |`,
    ),
    "",
    "Unknown metadata fields are rejected by `turn_into_object`.",
    "",
    "## Frontmatter of a vault file",
    "",
    "| Key | DB column | Note |",
    "| --- | --- | --- |",
    ...FRONTMATTER_GUIDE.map((k) => `| \`${k.key}\` | \`${k.column}\` | ${k.note} |`),
    "",
    "The body below the frontmatter is `content_md`.",
    "",
    "## MCP tools",
    "",
    ...TOOL_GUIDE.flatMap((t) => [`- **\`${t.name}\`**: ${t.use}`, `  \`${json(t.example)}\``]),
    "",
    "## Conventions",
    "",
    ...CONVENTIONS.map((c) => `- ${c}`),
    "",
  );
  return brand(out.join("\n"));
}

/** Max folders listed in the index (the rest is summarised in one line). */
export const FOLDER_INDEX_LIMIT = 400;

/**
 * The user's folder index (sitemap): every folder with its direct item count and the total
 * including sub-folders. Folders without a row (only items) are added; ancestors too.
 */
export function renderFolderIndex(
  folders: readonly FolderCount[],
  opts: { title?: string; limit?: number } = {},
): string {
  const direct = new Map<string, number>();
  const add = (path: string, n: number) => direct.set(path, (direct.get(path) ?? 0) + n);
  for (const f of folders) {
    const path = f.folder_path.replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
    if (!path) continue;
    add(path, f.items);
    const parts = path.split("/");
    for (let i = 1; i < parts.length; i++) add(parts.slice(0, i).join("/"), 0);
  }
  const paths = [...direct.keys()].sort((a, b) => a.localeCompare(b, "en"));
  const total = (p: string) =>
    paths
      .filter((q) => q === p || q.startsWith(`${p}/`))
      .reduce((sum, q) => sum + (direct.get(q) ?? 0), 0);
  const limit = opts.limit ?? FOLDER_INDEX_LIMIT;
  const allItems = paths.reduce((sum, p) => sum + (direct.get(p) ?? 0), 0);
  const lines = [
    `## ${opts.title ?? "Folder index"}`,
    "",
    `${paths.length} folders, ${allItems} items. Count = items in the folder (with sub-folders in brackets).`,
    "",
  ];
  for (const p of paths.slice(0, limit)) {
    const depth = p.split("/").length - 1;
    const name = p.slice(p.lastIndexOf("/") + 1);
    const own = direct.get(p) ?? 0;
    const sum = total(p);
    lines.push(`${"  ".repeat(depth)}- \`${name}/\` ${own}${sum !== own ? ` (${sum})` : ""}`);
  }
  if (paths.length > limit) lines.push(`- … ${paths.length - limit} more folders`);
  lines.push("");
  return lines.join("\n");
}

/** Guide + folder index, as served over MCP and written into the vault. */
export function renderAgentsDocument(
  folders: readonly FolderCount[] | null,
  opts: { indexTitle?: string; generatedAt?: Date } = {},
): string {
  const parts = [renderAgentsGuide()];
  if (folders) parts.push(renderFolderIndex(folders, { title: opts.indexTitle }));
  if (opts.generatedAt) parts.push(`_Generated ${opts.generatedAt.toISOString()}._`, "");
  return parts.join("\n");
}
